def remove_column(list1, n):
    """The program dawnr proved in `t`, written in Python (checked against `t`, not itself proved).

    requires n >= 0
    requires forall i in [0, len(list1)) . n < len(list1[i])
    ensures  len(r) == len(list1)
    ensures  forall i in [0, len(r)) . len(r[i]) == len(list1[i]) - 1
    ensures  forall i in [0, len(r)) . forall j in [0, n) . r[i][j] == list1[i][j]
    ensures  forall i in [0, len(r)) . forall j in [n, len(r[i])) . r[i][j] == list1[i][j + 1]

    Outside its `requires` it raises ValueError: nothing was proved there.
    """
    if not (_t_ints(list1, 2)):
        raise TypeError('remove_column: `list1` must be a list of lists of integers; nothing was proved for anything else')
    if not (_t_ints(n, 0)):
        raise TypeError('remove_column: `n` must be an integer; nothing was proved for anything else')
    list1 = _t_tuple(list1)
    if not _t_requires(list1, n):
        raise ValueError('remove_column: this input is outside what was proved (requires n >= 0; forall i in [0, len(list1)) . n < len(list1[i]))')
    _t_result = _t_core(list1, n)
    return _t_list(_t_result)

def _t_core(list1, n):
    r = ()
    i = 0
    # invariant: 0 <= i
    # invariant: i <= len(list1)
    # invariant: len(r) == i
    # invariant: forall k in [0, i) . len(r[k]) == len(list1[k]) - 1
    # invariant: forall k in [0, i) . forall j in [0, n) . r[k][j] == list1[k][j]
    # invariant: forall k in [0, i) . forall j in [n, len(r[k])) . r[k][j] == list1[k][j + 1]
    # decreases: len(list1) - i
    while (i < len(list1)):
        row = list1[i]
        new_row = (row[0:n] + row[(n + 1):len(row)])
        r = (r + (new_row, ))
        i = (i + 1)
    return r

def _t_requires(list1, n):
    try:
        return bool((n >= 0)) and bool(all((n < len(list1[i])) for i in range(0, len(list1))))
    except (IndexError, ZeroDivisionError):   # a `requires` with no value here admits nothing
        return False

def _t_tuple(v):
    return tuple(_t_tuple(x) for x in v) if isinstance(v, (list, tuple)) else v

def _t_ints(v, depth):
    if depth == 0:
        return isinstance(v, int) and not isinstance(v, bool)
    return isinstance(v, (list, tuple)) and all(_t_ints(x, depth - 1) for x in v)

def _t_list(v):
    return [_t_list(x) for x in v] if isinstance(v, tuple) else v

